import { createEffect, For, Show } from "solid-js";

import useStore from "@/chat-api/store/useStore";
import {
  StorageKeys,
  useChatBarOptions,
  useLocalStorage,
} from "@/common/localStorage";
import Checkbox from "../ui/Checkbox";
import Breadcrumb, { BreadcrumbItem } from "../ui/Breadcrumb";
import { t } from "@nerimity/i18lite";
import SettingsBlock from "../ui/settings-block/SettingsBlock";
import { useWindowProperties } from "@/common/useWindowProperties";
import {
  themePresets,
  applyTheme,
  currentTheme,
  customColors,
  setThemeColor,
  DefaultTheme,
} from "@/common/themes";
import { ColorPicker } from "../ui/color-picker/ColorPicker";
import Button from "../ui/Button";
import env from "@/common/env";
import style from "./InterfaceSettings.module.css";
import { useNavigate } from "solid-navigator";
import { FlexColumn } from "../ui/Flexbox";

export default function InterfaceSettings() {
  const { header } = useStore();

  createEffect(() => {
    header.updateHeader({
      title:
        t("settings.drawer.title") + " - " + t("settings.drawer.interface"),
      iconName: "settings",
    });
  });

  return (
    <div class={style.container}>
      <Breadcrumb>
        <BreadcrumbItem href="/app" icon="home" title={t("dashboard.title")} />
        <BreadcrumbItem title={t("settings.drawer.interface")} />
      </Breadcrumb>
      <ThemesBlock />
      <BlurEffect />
      <AdvancedMarkup />
      <ChatBar />
      <CustomizeColors />
      <SettingsBlock
        icon="code"
        label={t("settings.interface.customCSS")}
        href="./custom-css"
      />
      <ErudaBlock />
    </div>
  );
}

export function ThemesBlock() {
  const navigate = useNavigate();

  return (
    <SettingsBlock
      icon="style"
      label={t("settings.interface.themes")}
      description={t("settings.interface.themesDescription")}
      class={style.themeSettingsBlock}
    >
      <div class={style.themeGrid}>
        <For each={Object.entries(themePresets)}>
          {([name, { colors, maintainers }]) => {
            const displayColors =
              Object.keys(colors).length === 0
                ? currentTheme()
                : { ...DefaultTheme, ...colors };
            return (
              <div
                class={style.themeCard}
                style={{
                  "background-color": colors["pane-color"],
                  color: colors["text-color"],
                }}
              >
                <div class={style.themeName}>{name}</div>
                <Show when={maintainers.length}>
                  <div class={style.maintainers}>
                    {t("settings.interface.maintainers")}:{" "}
                    {maintainers.join(", ")}
                  </div>
                </Show>
                <div class={style.colorPreview}>
                  <For each={Object.values(displayColors)}>
                    {(color) => (
                      <div
                        class={style.colorBlock}
                        style={{ "background-color": color }}
                      />
                    )}
                  </For>
                </div>
                <Button
                  label={t("settings.interface.apply")}
                  onClick={() => applyTheme(name)}
                />
              </div>
            );
          }}
        </For>

        <div
          class={style.themeCard}
          style={{
            "background-color": "rgba(255,255,255,0.05)",
            "backdrop-filter": "blur(6px)",
            color: "#fff",
            display: "flex",
            "flex-direction": "column",
            "justify-content": "center",
            "align-items": "center",
            position: "relative",
            transition: "transform 0.2s, opacity 0.2s",
            border: "1px dashed rgba(255, 255, 255, 0.3)",
          }}
          onMouseEnter={(e) =>
            ((e.currentTarget as HTMLDivElement).style.transform =
              "translateY(-3px)")
          }
          onMouseLeave={(e) =>
            ((e.currentTarget as HTMLDivElement).style.transform =
              "translateY(0)")
          }
        >
          <div
            style={{
              "font-weight": "bold",
              "font-size": "1rem",
              "text-align": "center",
            }}
          >
            {t("settings.account.browse")}
          </div>
          <div
            style={{
              "text-align": "center",
              "margin-top": "4px",
              "font-size": "0.75rem",
            }}
          >
            {t("explore.themes.unlockDescription")}
          </div>

          <Button
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              opacity: 0,
              border: "none",
              background: "transparent",
              cursor: "pointer",
            }}
            onClick={() => navigate("/app/explore/themes")}
            iconName="explore"
          />
        </div>
      </div>
    </SettingsBlock>
  );
}

function ChatBar() {
  const { isMobileAgent } = useWindowProperties();
  const [chatBarOptions, setChatBarOptions] = useChatBarOptions();
  const options = [
    {
      id: "vm",
      icon: "mic",
      label: "Voice Message",
    },
    {
      id: "gif",
      icon: "gif",
      label: "GIF Picker",
    },
    {
      id: "emoji",
      icon: "face",
      label: "Emoji Picker",
    },
    ...(!isMobileAgent()
      ? [
          {
            id: "send",
            icon: "send",
            label: "Send",
          } as const,
        ]
      : []),
  ] as const;

  type OptionIds = ["vm", "gif", "emoji", "send"];

  return (
    <FlexColumn>
      <SettingsBlock
        icon="chat"
        label={t("settings.interface.chatBarOptions")}
        header
      />
      <For each={options}>
        {({ icon, label, id }) => (
          <SettingsBlock
            icon={icon}
            label={label}
            borderTopRadius={false}
            borderBottomRadius={false}
            onClick={() => {
              const options = chatBarOptions() as unknown as OptionIds[];
              if (chatBarOptions().includes(id)) {
                setChatBarOptions(
                  options.filter(
                    (i) => i !== (id as unknown as OptionIds)
                  ) as unknown as OptionIds
                );
              } else {
                setChatBarOptions([
                  ...chatBarOptions(),
                  id,
                ] as unknown as OptionIds);
              }
            }}
          >
            <Checkbox checked={chatBarOptions().includes(id)} />
          </SettingsBlock>
        )}
      </For>
    </FlexColumn>
  );
}

function ErudaBlock() {
  return (
    <SettingsBlock
      icon="bug_report"
      label={t("settings.interface.enableEruda")}
      description={t("settings.interface.enableErudaDescription")}
    >
      <Button
        label={t("settings.interface.enableOnce")}
        alert
        href={env.APP_URL + "/app?eruda=true"}
      />
    </SettingsBlock>
  );
}

function BlurEffect() {
  const { setBlurEffectEnabled, blurEffectEnabled } = useWindowProperties();
  const toggleBlurEffect = () => {
    setBlurEffectEnabled(!blurEffectEnabled());
  };

  return (
    <SettingsBlock
      icon="dvr"
      label={t("settings.interface.blurEffect")}
      description={t("settings.interface.blurEffectDescription")}
    >
      <Checkbox onChange={toggleBlurEffect} checked={blurEffectEnabled()} />
    </SettingsBlock>
  );
}
function AdvancedMarkup() {
  const [enabled, setEnabled] = useLocalStorage(
    StorageKeys.DISABLED_ADVANCED_MARKUP,
    false
  );

  return (
    <SettingsBlock
      icon="dvr"
      label={t("settings.interface.disableAdvancedMarkupBar")}
      description={t("settings.interface.disableAdvancedMarkupBarDescription")}
    >
      <Checkbox onChange={setEnabled} checked={enabled()} />
    </SettingsBlock>
  );
}

function CustomizeColors() {
  return (
    <div>
      <SettingsBlock
        icon="palette"
        label={t("settings.interface.customizeColors")}
        description={t("settings.interface.customizeColorsDescription")}
        header
      />
      <For each={Object.entries(currentTheme())}>
        {([name, value], i) => (
          <SettingsBlock
            icon="colors"
            class={style.themeItem}
            label={name.replaceAll("-", " ")}
            borderBottomRadius={i() === Object.keys(currentTheme()).length - 1}
            borderTopRadius={false}
          >
            <Show when={customColors()[name] && DefaultTheme[name] !== value}>
              <Button
                iconName="restart_alt"
                padding={2}
                onClick={() => setThemeColor(name, undefined)}
              />
            </Show>
            <ColorPicker
              alpha
              color={value}
              onChange={(v) => setThemeColor(name, v)}
            />
          </SettingsBlock>
        )}
      </For>
    </div>
  );
}
